import { validateNodes } from './validate-nodes.mjs';

export function planBuild(nodes) {
  validateNodes(nodes);
  if (nodes.length === 0) return [];

  const orderIndex = new Map(nodes.map((node, index) => [node.id, index]));
  const inDegree = new Map();
  const dependents = new Map();

  for (const node of nodes) {
    inDegree.set(node.id, 0);
    dependents.set(node.id, []);
  }

  for (const node of nodes) {
    const deps = [...new Set(node.dependsOn ?? [])];
    inDegree.set(node.id, deps.length);
    for (const dep of deps) {
      dependents.get(dep).push(node.id);
    }
  }

  const schedule = [];
  const scheduled = new Set();

  while (schedule.length < nodes.length) {
    const ready = nodes
      .filter((node) => !scheduled.has(node.id) && inDegree.get(node.id) === 0)
      .sort((a, b) => orderIndex.get(a.id) - orderIndex.get(b.id));

    if (ready.length === 0) {
      throw new Error('cycle');
    }

    const next = ready[0];
    scheduled.add(next.id);
    schedule.push(next.id);

    for (const dependent of dependents.get(next.id)) {
      inDegree.set(dependent, inDegree.get(dependent) - 1);
    }
  }

  return schedule;
}

