export function validateNodes(nodes) {
  if (!Array.isArray(nodes)) throw new TypeError('nodes must be an array');

  const seenIds = new Set();
  const ids = new Set();

  for (const node of nodes) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('node must be an object');
    }
    if (typeof node.id !== 'string' || node.id.length === 0) {
      throw new TypeError('node id must be a nonempty string');
    }
    if (seenIds.has(node.id)) {
      throw new Error('duplicate node id');
    }
    seenIds.add(node.id);
    ids.add(node.id);

    if (node.dependsOn !== undefined) {
      if (!Array.isArray(node.dependsOn)) {
        throw new TypeError('dependsOn must be an array');
      }
      for (const dep of node.dependsOn) {
        if (typeof dep !== 'string' || dep.length === 0) {
          throw new TypeError('dependency id must be a nonempty string');
        }
      }
    }
  }

  for (const node of nodes) {
    const deps = [...new Set(node.dependsOn ?? [])];
    for (const dep of deps) {
      if (!ids.has(dep)) {
        throw new Error('missing dependency');
      }
      if (dep === node.id) {
        throw new Error('cycle');
      }
    }
  }

  const state = new Map();
  for (const id of ids) state.set(id, 0);

  function visit(id) {
    state.set(id, 1);
    const node = nodes.find((n) => n.id === id);
    const deps = [...new Set(node.dependsOn ?? [])];
    for (const dep of deps) {
      const s = state.get(dep);
      if (s === 1) throw new Error('cycle');
      if (s === 0) visit(dep);
    }
    state.set(id, 2);
  }

  for (const id of ids) {
    if (state.get(id) === 0) visit(id);
  }

  return nodes;
}

